import re, zipfile, os
import openpyxl
from openpyxl.utils import get_column_letter

out = '/root/output/result.xlsx'
recalc = '/root/output/result_recalc.xlsx'
sheet_xml = 'xl/worksheets/sheet1.xml'

# Read recalculated numeric values
wbv = openpyxl.load_workbook(recalc, data_only=True)
tv = wbv['Task']

target_rows = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32)) + list(range(35, 41)) + list(range(42, 48)) + [50]
values = {}
for r in target_rows:
    for c in range(8, 13):
        coord = f'{get_column_letter(c)}{r}'
        v = tv.cell(r, c).value
        if not isinstance(v, (int, float)):
            raise SystemExit(f'Non-numeric recalculated value at {coord}: {v!r}')
        values[coord] = v

# Read existing package entries
with zipfile.ZipFile(out, 'r') as zin:
    entries = {name: zin.read(name) for name in zin.namelist()}

text = entries[sheet_xml].decode('utf-8')
for coord, val in values.items():
    pat = re.compile(r'(<c r="' + coord + r'"[^>]*>.*?<f>.*?</f>)<v></v>(</c>)', re.S)
    val_s = format(val, '.15g')
    text, n = pat.subn(lambda m, v=val_s: m.group(1) + f'<v>{v}</v>' + m.group(2), text, count=1)
    if n != 1:
        raise SystemExit(f'Could not patch formula cell {coord} (matches={n})')
entries[sheet_xml] = text.encode('utf-8')

# Write updated package atomically
tmp = out + '.tmp'
with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as zout:
    for name, data in entries.items():
        zout.writestr(name, data)
os.replace(tmp, out)

# Verify formula mode and value mode
wbf = openpyxl.load_workbook(out, data_only=False)
wbv2 = openpyxl.load_workbook(out, data_only=True)
wsf = wbf['Task']
wsv = wbv2['Task']

formula_count = 0
value_count = 0
for r in target_rows:
    for c in range(8, 13):
        f = wsf.cell(r, c).value
        v = wsv.cell(r, c).value
        assert isinstance(f, str) and f.startswith('='), f'Missing formula at {get_column_letter(c)}{r}: {f!r}'
        assert isinstance(v, (int, float)), f'Missing numeric cached value at {get_column_letter(c)}{r}: {v!r}'
        formula_count += 1
        value_count += 1

# Specific formula sanity checks
for r in range(12, 18):
    for c in range(8, 13):
        assert 'INDEX(Data!' in wsf.cell(r, c).value and 'MATCH($D' in wsf.cell(r, c).value
for r in range(19, 25):
    for c in range(8, 13):
        assert 'INDEX(Data!' in wsf.cell(r, c).value and 'MATCH($D' in wsf.cell(r, c).value
for r in range(26, 32):
    for c in range(8, 13):
        assert 'INDEX(Data!' in wsf.cell(r, c).value and 'MATCH($D' in wsf.cell(r, c).value
for r in range(35, 41):
    for c in range(8, 13):
        assert '*100' in wsf.cell(r, c).value and '/' in wsf.cell(r, c).value
for r in range(42, 43):
    for c in range(8, 13):
        assert wsf.cell(r, c).value.startswith('=MIN(')
for r in range(43, 44):
    for c in range(8, 13):
        assert wsf.cell(r, c).value.startswith('=MAX(')
for r in range(44, 45):
    for c in range(8, 13):
        assert wsf.cell(r, c).value.startswith('=MEDIAN(')
for r in range(45, 46):
    for c in range(8, 13):
        assert wsf.cell(r, c).value.startswith('=AVERAGE(')
for r in range(46, 48):
    for c in range(8, 13):
        assert 'PERCENTILE(' in wsf.cell(r, c).value
for c in range(8, 13):
    assert wsf.cell(50, c).value.startswith('=SUMPRODUCT(') and wsf.cell(50, c).value.count('/SUM(') == 1

print(f'Verified {formula_count} formula cells with cached numeric values')
print('Sample formulas/values:')
for coord in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','L47','H50','L50']:
    c = ord(coord[0]) - ord('A') + 1
    r = int(coord[1:])
    print(coord, wsf.cell(r,c).value, '=>', wsv.cell(r,c).value)
